size_t i = *tabind;
while (i < ckh->lg_cur + ckh->lg_old) {
    size_t mask = (1ULL << (i < ckh->lg_cur ? ckh->lg_cur : ckh->lg_old)) - 1;
    size_t idx = i & mask;
    void **tbl = (i < ckh->lg_cur) ? ckh->tab_cur : ckh->tab_old;
    if (tbl[idx] != nullptr) {
        *key = tbl[idx];
        *data = tbl[idx + 1];
        *tabind = i + 1;
        return false;
    }
    i++;
}
*tabind = i;
return true;
